export type PageHeaderProps = {
  readonly title: string;
  readonly subtitle?: ReactNode;
  readonly icon?: ReactNode;
  readonly headingLevel?: 2 | 3;
  /** The only visible primary action owned by this page context. */
  readonly primaryAction?: ReactNode;
  /** Frequent, non-destructive actions that remain visible beside the primary. */
  readonly secondaryActions?: ReactNode;
  /** Low-frequency or destructive non-primary actions, exposed through a menu. */
  readonly overflowActions?: readonly DropdownMenuItem[];
  /** Contextual controls that belong to the header rather than the toolbar. */
  readonly contextualControls?: ReactNode;
  readonly actionsLabel?: string;
};

export function PageHeader({
  title,
  subtitle,
  icon,
  headingLevel = 2,
  primaryAction,
  secondaryActions,
  overflowActions = [],
  contextualControls,
  actionsLabel = `Acciones de ${title}`,
}: PageHeaderProps): ReactNode {
  const heading = headingLevel === 2
    ? <h2 className="page-header__title">{title}</h2>
    : <h3 className="page-header__title">{title}</h3>;
  const hasActions = primaryAction || secondaryActions || overflowActions.length > 0;

  return (
    <header className="page-header" data-testid="page-header">
      <div className="page-header__identity">
        {icon ? <span className="page-header__icon" aria-hidden>{icon}</span> : null}
        <div className="page-header__copy">
          {heading}
          {subtitle ? <p className="page-header__subtitle">{subtitle}</p> : null}
        </div>
      </div>
      {hasActions || contextualControls ? (
        <div className="page-header__action-slot" aria-label={actionsLabel}>
          {contextualControls ? (
            <div className="page-header__contextual-controls">{contextualControls}</div>
          ) : null}
          {secondaryActions ? (
            <div className="page-header__secondary-actions">{secondaryActions}</div>
          ) : null}
          {overflowActions.length > 0 ? (
            <DropdownMenu
              ariaLabel={actionsLabel}
              triggerLabel="Más acciones"
              triggerIcon={<MoreHorizontal size={16} strokeWidth={1.5} aria-hidden />}
              triggerClassName="btn btn--ghost page-header__overflow-trigger"
              sections={[{ id: 'page-actions', items: overflowActions }]}
            />
          ) : null}
          {primaryAction ? <div className="page-header__primary-action">{primaryAction}</div> : null}
        </div>
      ) : null}
    </header>
  );

export type PageToolbarProps = {
  readonly ariaLabel: string;
  readonly search?: ReactNode;
  readonly filters?: ReactNode;
  readonly tabs?: ReactNode;
  readonly contextualControls?: ReactNode;
};

export function PageToolbar({
  ariaLabel,
  search,
  filters,
  tabs,
  contextualControls,
}: PageToolbarProps): ReactNode {
  if (!search && !filters && !tabs && !contextualControls) return null;

  return (
    <div className="page-toolbar" aria-label={ariaLabel} data-testid="page-toolbar">
      {search ? <div className="page-toolbar__search">{search}</div> : null}
      {filters ? <div className="page-toolbar__filters">{filters}</div> : null}
      {tabs ? <div className="page-toolbar__tabs">{tabs}</div> : null}
      {contextualControls ? (
        <div className="page-toolbar__contextual-controls">{contextualControls}</div>
      ) : null}
    </div>
  );

function Tabs<TTabId extends string>({
  tabs,
  activeTab,
  onTabChange,
  ariaLabel,
  idPrefix,
  testIdPrefix,
  variant,
}: TabsProps<TTabId> & { readonly variant: 'workspace' | 'workflow' }): ReactNode {
  const tabIds = tabs.filter((tab) => !tab.disabled).map((tab) => tab.id);
  const rovingTabs = useRovingTabList({
    tabIds,
    selectedId: activeTab,
    onSelect: onTabChange,
  });

  return (
    <nav
      className={`tabs tabs--${variant}`}
      role="tablist"
      aria-label={ariaLabel}
      {...rovingTabs.tabListProps}
      data-testid={testIdPrefix ? `${testIdPrefix}-tablist` : undefined}
    >
      <div className="tabs__scroller">
        {tabs.map((tab) => {
          const selected = activeTab === tab.id;
          const enabledIndex = tabIds.indexOf(tab.id);
          return (
            <button
              key={tab.id}
              type="button"
              role="tab"
              {...(enabledIndex >= 0 ? rovingTabs.tabPropsAt(enabledIndex) : { tabIndex: -1 })}
              id={`${idPrefix}-tab-${tab.id}`}
              aria-selected={selected}
              aria-controls={`${idPrefix}-panel-${tab.id}`}
              disabled={tab.disabled}
              title={tab.title}
              className={`tabs__tab ${selected ? 'tabs__tab--active' : ''}`}
              onClick={() => onTabChange(tab.id)}
              data-testid={testIdPrefix ? `${testIdPrefix}-tab-${tab.id}` : undefined}
            >
              {tab.icon}
              {tab.label}
              {tab.count !== undefined ? (
                <span className="tabs__count" aria-label={`${tab.count} elementos`}>
                  {tab.count}
                </span>
              ) : null}
              {tab.alert ? (
                <span className="tabs__alert" title={tab.title ?? 'Atención'}>
                  !
                </span>
              ) : null}
            </button>
          );
        })}
      </div>
    </nav>
  );
}

export function WorkspaceTabs<TTabId extends string>(props: TabsProps<TTabId>): ReactNode {
  return <Tabs {...props} variant="workspace" />;
}

export function WorkflowTabs<TTabId extends string>(props: TabsProps<TTabId>): ReactNode {
  return <Tabs {...props} variant="workflow" />;
}

