  for (const scenario of fx.scenarios) {
    it(`${scenario.id}: ${scenario.description}`, () => {
      const module = moduleForScenario(scenario.agregadoQty, scenario.moduleId);
      const project = projectForScenario(scenario, scenario.moduleId);
      const item = project.items[0]!;

      // 1) BOM: piezas por firma (description + dims + material) y multiplicidad.
      const bom = resolveBom(
        module,
        item.optionChoices,
        { ...fx.catalog, modules: [module] },
        item.measurePresetId,
        undefined,
        undefined,
        item.customDims,
      );

      const counts = new Map<string, number>();
      for (const part of bom.boardParts) {
        const key = partSignatureKey(part);
        counts.set(key, (counts.get(key) ?? 0) + part.quantity);
      }
      expect([...counts.entries()].sort()).toEqual(
        scenario.expected.parts
          .map((p) => [partSignatureKey(p), p.count] as [string, number])
          .sort(),
      );

      // Anti-leak ambiental: ningún id ambiental puede aparecer en el BOM.
      for (const part of bom.boardParts) {
        expect(fx.ambientMaterialIds).not.toContain(part.materialId);
      }

      // 2) Hardware: agregado por hardwareId resuelto (TS emite N líneas qty 1,
      //    Go 1 línea qty N — el costo coincide; el contract congela el total).
      const hardwareTotals = new Map<string, number>();
      for (const line of bom.hardwareLines) {
        hardwareTotals.set(
          line.hardwareId,
          (hardwareTotals.get(line.hardwareId) ?? 0) + line.quantity,
        );
      }
      expect(Object.fromEntries([...hardwareTotals.entries()].sort())).toEqual(
        Object.fromEntries(
          Object.entries(scenario.expected.hardwareTotals).sort(),
        ),
      );

      // 3) Precio: breakdown completo del proyecto (mismo policy de no
      //    redondeo intermedio que Go; tolerancia 0.01 del golden).
      const catalog = { ...fx.catalog, modules: [module] };
      const breakdown = calcProjectBreakdown(project, catalog);
      expect(breakdown.materialsCost).toBeCloseTo(
        scenario.expected.materialsCost,
        2,
      );
      expect(breakdown.hardwareTotal).toBeCloseTo(
        scenario.expected.hardwareTotal,
        2,
      );
      expect(breakdown.directCost).toBeCloseTo(
        scenario.expected.directCost,
        2,
      );
      expect(breakdown.salePrice).toBeCloseTo(scenario.expected.salePrice, 2);
    });
  }

func TestDesignBomPriceContract(t *testing.T) {
	f := loadFixture(t)
	baseItem := f.Project.Items[0]

	for _, sc := range f.Scenarios {
		sc := sc
		t.Run(sc.ID, func(t *testing.T) {
			mod := f.moduleForScenario(sc)
			catalog := f.catalogWithModule(mod)

			choices := map[string]string{}
			for k, v := range baseItem.OptionChoices {
				choices[k] = v
			}
			for k, v := range sc.OptionChoicesOverride {
				choices[k] = v
			}
			item := domain.ProjectItem{
				ID: baseItem.ID, ModuleID: mod.ID,
				Quantity: baseItem.Quantity, OptionChoices: choices,
				MeasurePresetID: baseItem.MeasurePresetID,
				CustomDims:      sc.CustomDims.toDomain(),
			}
			project := domain.Project{
				ID: f.Project.ID, Name: f.Project.Name, CustomerID: f.Project.CustomerID,

		hwTotals := map[string]float64{}
		for _, line := range bom.HardwareLines {
			hwTotals[line.HardwareID] += line.Quantity
		}
		if len(hwTotals) != len(sc.Expected.HardwareTotals) {
			t.Fatalf("hardware totals divergen: got %v, want %v", hwTotals, sc.Expected.HardwareTotals)
		}
		for id, n := range sc.Expected.HardwareTotals {
			if hwTotals[id] != n {
				t.Errorf("hardware %q: got %v, want %v (got all: %v)", id, hwTotals[id], n, hwTotals)
			}
		}

		// 3) Precio: mismo policy de no redondeo intermedio que TS (tol 0.01).
		bd, err := CalcProjectBreakdown(project, catalog)
		if err != nil {
			t.Fatalf("CalcProjectBreakdown: %v", err)
		}
		if !almostEqual(bd.MaterialsCost, sc.Expected.MaterialsCost) {
			t.Errorf("materialsCost = %v, want %v", bd.MaterialsCost, sc.Expected.MaterialsCost)
		}
		if !almostEqual(bd.HardwareTotal, sc.Expected.HardwareTotal) {
			t.Errorf("hardwareTotal = %v, want %v", bd.HardwareTotal, sc.Expected.HardwareTotal)
		}
		if !almostEqual(bd.DirectCost, sc.Expected.DirectCost) {
			t.Errorf("directCost = %v, want %v", bd.DirectCost, sc.Expected.DirectCost)
		}
		if !almostEqual(bd.SalePrice, sc.Expected.SalePrice) {
			t.Errorf("salePrice = %v, want %v", bd.SalePrice, sc.Expected.SalePrice)
		}
	})
}

